function createSceneOverlay({U, typeOf, font, subscribeUpdate, camera, logoBytes, previous}) {
  const G=CS.Assets.Scripts.GameLogic, nodes=[], listeners=[], assets=[], pool=[];
  const flags={ray:false,box:false,hp:false,bones:false,distance:false,ignoreBots:false};
  const state={ticks:0,heroes:0,displayed:0,filteredBots:0,error:null};
  const color=(r,g,b,a=1)=>new U.Color(r,g,b,a), v2=(x,y)=>new U.Vector2(x,y);
  const alive=o=>o!=null && U.Object.op_Implicit(o), add=(go,t)=>go.AddComponent(typeOf(t));
  const started=Number(U.Time.realtimeSinceStartup);
  let disposed=false, unsubscribe, root, panel, capsule, opened=true, busy=false;
  let px=Math.max(0,(U.Screen.width-800)/2),py=Math.max(0,(U.Screen.height-490)/2);
  if(previous&&Number.isFinite(previous.panelX)&&Number.isFinite(previous.panelY)){px=previous.panelX;py=previous.panelY;}
  let prevDown=false,drag=null,nextScan=0,nextFrame=0,nextClock=0,actors=[],host=null,used=0;
  function node(name,parent,x,y,w,h){
    const go=new U.GameObject(name);nodes.push(go);const rect=add(go,U.RectTransform);
    if(parent)rect.SetParent(parent,false);
    rect.anchorMin=v2(0,0);rect.anchorMax=v2(0,0);rect.pivot=v2(0,0);
    rect.anchoredPosition=v2(x,y);rect.sizeDelta=v2(w,h);return {go,rect};
  }
  function image(parent,x,y,w,h,c,hit=false){const n=node('RTD_Image',parent,x,y,w,h);n.image=add(n.go,U.UI.Image);n.image.color=c;n.image.raycastTarget=hit;return n;}
  function roundedSprite(){
    const t=new U.Texture2D(32,32);assets.push(t);
    for(let y=0;y<32;y++)for(let x=0;x<32;x++){const dx=Math.max(0,8-x,x-23),dy=Math.max(0,8-y,y-23);t.SetPixel(x,y,color(1,1,1,Math.max(0,Math.min(1,8-Math.hypot(dx,dy)))));}
    t.Apply();const s=U.Sprite.Create(t,new U.Rect(0,0,32,32),v2(.5,.5),100,0,U.SpriteMeshType.FullRect,new U.Vector4(9,9,9,9));assets.push(s);return s;
  }
  function circleSprite(){
    const t=new U.Texture2D(32,32);assets.push(t);
    for(let y=0;y<32;y++)for(let x=0;x<32;x++)t.SetPixel(x,y,color(1,1,1,Math.max(0,Math.min(1,16-Math.hypot(x-15.5,y-15.5)))));
    t.Apply();const s=U.Sprite.Create(t,new U.Rect(0,0,32,32),v2(.5,.5));assets.push(s);return s;
  }
  function text(parent,value,x,y,w,h,size=22,align=U.TextAnchor.MiddleLeft){
    const n=node('RTD_Text',parent,x,y,w,h);n.text=add(n.go,U.UI.Text);n.text.font=font;n.text.fontSize=size;
    n.text.color=color(1,1,1);n.text.alignment=align;n.text.raycastTarget=false;n.text.text=value;return n;
  }
  function button(parent,value,x,y,w,h,fn,c=color(.16,.26,.34,.8)){
    const n=image(parent,x,y,w,h,c,true),b=add(n.go,U.UI.Button);b.targetGraphic=n.image;
    b.onClick.AddListener(fn);listeners.push([b,fn]);n.label=text(n.rect,value,0,0,w,h,22,U.TextAnchor.MiddleCenter);return n;
  }
  function stop(){if(disposed)return;disposed=true;if(unsubscribe)unsubscribe();
    for(const [b,f] of listeners){try{if(alive(b))b.onClick.RemoveListener(f)}catch(e){}}
    for(const go of nodes.reverse()){try{if(alive(go))U.Object.Destroy(go)}catch(e){}}
    for(const a of assets){try{U.Object.Destroy(a)}catch(e){}}actors=[];
  }
  const toggles={};
  function setFlag(key,on){if(!(key in flags))throw new Error('Unknown option');flags[key]=!!on;
    if(toggles[key]){const t=toggles[key];t.label.text.text=t.name+'   '+(flags[key]?'● 开':'○ 关');t.image.color=flags[key]?color(.06,.48,.8,.92):color(.12,.2,.28,.75);}
    nextFrame=0;
  }
  function primitive(kind){
    let p=pool[used];
    if(p && p.kind!==kind){p.go.SetActive(false);p=null;}
    if(!p){p=kind==='text'?text(root.rect,'',0,0,160,24,16,U.TextAnchor.MiddleCenter):image(root.rect,0,0,1,1,color(1,1,1));p.kind=kind;pool.splice(used,0,p);}
    used++;p.go.SetActive(true);return p;
  }
  function line(a,b,c,thickness=2){
    if(!a||!b)return;const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy);if(len<.5)return;
    const n=primitive('line');n.rect.anchoredPosition=v2(a.x,a.y);n.rect.sizeDelta=v2(len,thickness);
    n.rect.localEulerAngles=new U.Vector3(0,0,Math.atan2(dy,dx)*180/Math.PI);n.image.color=c;
  }
  function rect(x,y,w,h,c){const n=primitive('line');n.rect.anchoredPosition=v2(x,y);n.rect.sizeDelta=v2(w,h);n.rect.localEulerAngles=new U.Vector3(0,0,0);n.image.color=c;}
  function label(value,x,y){const n=primitive('text');n.text.text=value;n.rect.anchoredPosition=v2(x-80,y);}
  function hideUnused(){for(let i=used;i<pool.length;i++)pool[i].go.SetActive(false);panel.rect.SetAsLastSibling();capsule.rect.SetAsLastSibling();}
  const boneNames=['Pelvis','Spine','Spine1','Neck','Head','L Clavicle','L UpperArm','L Forearm','L Hand','R Clavicle','R UpperArm','R Forearm','R Hand','L Thigh','L Calf','L Foot','R Thigh','R Calf','R Foot'];
  function scan(){
    actors=[];host=null;const m=G.ActorManager.GetInstance(),players=G.GamePlayerCenter.GetInstance();if(!m||!players){state.heroes=0;return;}
    const id=Number(m.GetRawHostPlayerActorId()),count=m.GetHeroActorCount();state.heroes=count;
    for(let i=0;i<count;i++){const h=m.GetHeroActorByIndex(i);if(Number(h.objID)===id)host=h;}
    if(!host)return;
    for(let i=0;i<count;i++){
      const h=m.GetHeroActorByIndex(i);if(Number(h.objID)===id||h.objCamp===host.objCamp)continue;
      const renderer=h.SkinMeshRdr;if(!alive(renderer))continue;
      const player=players.GetPlayer(h.playerId),bot=player?(!!player.IsComputer||!!player.IsNPC()):null;
      const bones=renderer.bones,selected=[];
      for(let j=0;j<bones.Length;j++){const b=bones.get_Item(j);if(alive(b)&&boneNames.some(n=>String(b.name)==='Bip001 '+n))selected.push(b);}
      const links=[];for(const b of selected){let p=b.parent;for(let depth=0;alive(p)&&depth<6;depth++,p=p.parent){if(selected.some(s=>s.GetInstanceID()===p.GetInstanceID())){links.push([b,p]);break;}}}
      actors.push({h,renderer,bot,links});
    }
  }
  function draw(now){
    used=0;state.displayed=0;state.filteredBots=0;
    if(!Object.keys(flags).some(k=>k!=='ignoreBots'&&flags[k])){hideUnused();return;}
    if(now>=nextScan){nextScan=now+1;scan();}
    const cam=camera();if(!alive(cam)||!host){hideUnused();return;}
    const width=Number(U.Screen.width),height=Number(U.Screen.height),origin=host.MyTransform.position;
    const project=p=>{const q=cam.WorldToScreenPoint(p);return q.z>cam.nearClipPlane?q:null;};
    for(const a of actors){
      if(flags.ignoreBots&&a.bot===true){state.filteredBots++;continue;}
      if(!alive(a.renderer)||!a.renderer.enabled||!a.renderer.gameObject.activeInHierarchy||!a.h.Visible)continue;
      const hp=Number(a.h.ValueComponent.ActorHp),max=Number(a.h.ValueComponent.ActorHpTotal);if(hp<=0)continue;
      const bounds=a.renderer.bounds,c=bounds.center,e=bounds.extents,p=project(c);if(!p||p.x<0||p.x>width||p.y<0||p.y>height)continue;
      let x0=Infinity,y0=Infinity,x1=-Infinity,y1=-Infinity;
      for(const sx of [-1,1])for(const sy of [-1,1])for(const sz of [-1,1]){const q=project(new U.Vector3(c.x+sx*e.x,c.y+sy*e.y,c.z+sz*e.z));if(q){x0=Math.min(x0,q.x);y0=Math.min(y0,q.y);x1=Math.max(x1,q.x);y1=Math.max(y1,q.y)}}
      if(!Number.isFinite(x0))continue;state.displayed++;const white=color(1,.35,.25),cyan=color(.2,.9,1);
      if(flags.ray)line({x:width/2,y:height-4},{x:p.x,y:y1},white,1.5);
      if(flags.box){line({x:x0,y:y0},{x:x1,y:y0},white);line({x:x1,y:y0},{x:x1,y:y1},white);line({x:x1,y:y1},{x:x0,y:y1},white);line({x:x0,y:y1},{x:x0,y:y0},white);}
      if(flags.hp&&Number.isFinite(hp)&&max>0){const w=Math.max(60,x1-x0);rect(p.x-w/2,y1+6,w,6,color(0,0,0,.85));rect(p.x-w/2,y1+6,w*Math.min(1,Math.max(0,hp/max)),6,color(.1,1,.32));label(Math.round(hp)+' / '+Math.round(max),p.x,y1+13);}
      if(flags.distance){const t=a.h.MyTransform.position;label(Math.hypot(t.x-origin.x,t.y-origin.y,t.z-origin.z).toFixed(1)+' 单位',p.x,y0-25);}
      if(flags.bones)for(const [b,parent] of a.links){if(alive(b)&&alive(parent))line(project(b.position),project(parent.position),cyan,2);}
    }
    hideUnused();
  }
  try{
    root=node('RTD_HeroOverlay',null,0,0,0,0);U.Object.DontDestroyOnLoad(root.go);
    const canvas=add(root.go,U.Canvas);canvas.renderMode=U.RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=30000;add(root.go,U.UI.GraphicRaycaster);
    panel=image(root.rect,px,py,800,490,color(.035,.065,.095,.84),true);
    image(panel.rect,0,0,204,490,color(.055,.08,.12,.82));
    const round=roundedSprite();panel.image.sprite=round;panel.image.type=U.UI.Image.Type.Sliced;
    const dotColors=[color(1,.2,.25),color(1,.78,.05),color(.05,.9,.3)];
    const circle=circleSprite();
    for(let i=0;i<3;i++){const dot=image(panel.rect,18+i*25,459,16,16,dotColors[i]);dot.image.sprite=circle;}
    text(panel.rect,'RTD MOD',225,432,230,48,29);
    const clock=text(panel.rect,'',435,442,345,30,17,U.TextAnchor.MiddleRight);
    image(panel.rect,224,424,554,1,color(.5,.7,.9,.25));
    if(logoBytes){const texture=new U.Texture2D(2,2);assets.push(texture);if(!U.ImageConversion.LoadImage(texture,logoBytes,false))throw new Error('Logo load failed');const n=node('RTD_Logo',panel.rect,44,300,116,116);const raw=add(n.go,U.UI.RawImage);raw.texture=texture;raw.color=color(1,1,1);raw.raycastTarget=false;}
    else text(panel.rect,'RTD',30,310,145,100,42,U.TextAnchor.MiddleCenter);
    text(panel.rect,'运行：脚本',22,259,145,35,18);text(panel.rect,'●',173,263,22,25,19).text.color=dotColors[2];
    image(panel.rect,12,196,180,45,color(.14,.4,.57,.85));
    const icon=image(panel.rect,22,204,28,28,color(.05,.8,.25));text(icon.rect,'◎',0,0,28,28,22,U.TextAnchor.MiddleCenter);
    text(panel.rect,'绘制图画',60,198,130,40,23);
    text(panel.rect,'@hxuhdsi',16,22,172,32,16,U.TextAnchor.MiddleCenter);
    text(panel.rect,'绘制设置',229,357,510,45,27);
    const defs=[['ray','绘制射线'],['box','绘制方框'],['hp','绘制血量'],['bones','绘制骨骼'],['distance','绘制距离'],['ignoreBots','忽略人机']];
    defs.forEach(([key,name],i)=>{const n=button(panel.rect,'',226+(i%2)*279,280-Math.floor(i/2)*78,260,58,()=>setFlag(key,!flags[key]));n.name=name;toggles[key]=n;setFlag(key,false);});
    const status=text(panel.rect,'',228,50,550,34,18);
    capsule=button(root.rect,'RTD     菜单',U.Screen.width/2-110,U.Screen.height-85,220,44,()=>{opened=!opened;panel.go.SetActive(opened)},color(.04,.06,.08,.95));
    capsule.image.sprite=round;capsule.image.type=U.UI.Image.Type.Sliced;
    function update(){if(disposed||busy)return;busy=true;try{
      state.ticks++;if(!alive(root.go)){stop();return;}const now=Number(U.Time.realtimeSinceStartup);
      if(now>=nextClock){nextClock=now+1;const secs=Math.max(0,Math.floor(now-started)),pad=n=>String(n).padStart(2,'0');clock.text.text='本次已使用时间：'+pad(Math.floor(secs/3600))+':'+pad(Math.floor(secs/60)%60)+':'+pad(secs%60);}
      let p,down;if(U.Input.touchCount>0){const t=U.Input.GetTouch(0);p=t.position;down=t.phase!==U.TouchPhase.Ended&&t.phase!==U.TouchPhase.Canceled;}else{p=U.Input.mousePosition;down=U.Input.GetMouseButton(0);}
      if(opened&&down&&!prevDown&&p.x>=px&&p.x<=px+800&&p.y>=py+428&&p.y<=py+490)drag={x:p.x-px,y:p.y-py};
      if(down&&drag){px=Math.max(0,Math.min(p.x-drag.x,U.Screen.width-800));py=Math.max(0,Math.min(p.y-drag.y,U.Screen.height-490));panel.rect.anchoredPosition=v2(px,py);}
      if(!down)drag=null;prevDown=down;
      if(now>=nextFrame){nextFrame=now+.05;draw(now);state.error=null;status.text.text=state.displayed?'显示 '+state.displayed+' 个目标':'';}
    }catch(e){state.error=String(e);used=0;hideUnused();status.text.text='绘制接口异常';}finally{busy=false;}}
    unsubscribe=subscribeUpdate(update);
    if(previous&&previous.flags)for(const k of Object.keys(flags))setFlag(k,previous.flags[k]);
    return {stop,setFlag,getStatus:()=>({...state,flags:{...flags},disposed,panelX:px,panelY:py,opened,pool:pool.length})};
  }catch(e){stop();throw e;}
}


(function () {
  const previous=globalThis.__rtdSceneOverlay?globalThis.__rtdSceneOverlay.getStatus():null;
  if (globalThis.__rtdSceneOverlay) globalThis.__rtdSceneOverlay.stop();
  const texts = U.Object.FindObjectsOfType(puerts.$typeof(U.UI.Text));
  let font;
  for (let i=0;i<texts.Length;i++) {
    const t = texts.get_Item(i);
    if (t.font) {font=t.font;break;}
  }
  if (!font) throw new Error('No existing UI font');
  let cachedCamera = null, cameraRefresh = 0;
  function getCamera() {
    const now = U.Time.realtimeSinceStartup;
    if (now < cameraRefresh && cachedCamera && U.Object.op_Implicit(cachedCamera)) return cachedCamera;
    cameraRefresh = now + 1;
    const main = U.Camera.main;
    if (main && U.Object.op_Implicit(main) && main.enabled) { cachedCamera=main;return main; }
    const cams = U.Object.FindObjectsOfType(puerts.$typeof(U.Camera));
    cachedCamera = null;
    for (let i=0;i<cams.Length;i++) {
      const c=cams.get_Item(i);
      if (!c.enabled || !c.gameObject.activeInHierarchy || c.cullingMask === 32 || c.cullingMask === 16 || c.cullingMask === 0) continue;
      if (!cachedCamera || c.depth < cachedCamera.depth) cachedCamera=c;
    }
    return cachedCamera;
  }
  globalThis.__rtdSceneOverlay = createSceneOverlay({
    U, typeOf: puerts.$typeof, font, camera: getCamera, previous, logoBytes: CS.System.Convert.FromBase64String(""),
    subscribeUpdate(fn) {
      U.Canvas.add_willRenderCanvases(fn);
      return () => U.Canvas.remove_willRenderCanvases(fn);
    }
  });
  return JSON.stringify({created:true,status:globalThis.__rtdSceneOverlay.getStatus()});
})()
